/*
 * Windows specific: there are no fifos and no job control in the POSIX
 * sense.  Process substitution is implemented with pipes; the shell
 * opens the other end of the pipe through the pseudo file /dev/fd/N,
 * which the compatibility layer maps onto the file descriptor N.
 */
#undef HAVE_FIFOS
#define PATH_DEV_FD "/dev/fd"

