/*
 * The random number generator of the shell uses the system random
 * number generator; getrandom() is implemented on top of BCrypt.
 */
#define HAVE_GETRANDOM 1
/*
 * The shell works out the current directory with getcwd(): walking up
 * the hierarchy with ".." does not work on Windows.
 */
#define USE_GETCWD 1
